    public DateTimeOffset CreatedUtc{get;} public string CreatedBy{get;} public string SubmissionSchemaVersion{get;} public DocumentaryNarrativeRevisionEditorType EditorType{get;} public string EditorName{get;} public string CorrelationId{get;}
}

public sealed class DocumentaryNarrativePassageRevisionSubmission
{
    public DocumentaryNarrativePassageRevisionSubmission(string workItemId,string passageId,string originalText,string revisedText,IReadOnlyList<string> resolvedRevisionItemIds)
    { WorkItemId=Guard.Required(workItemId,nameof(workItemId)); PassageId=Guard.Required(passageId,nameof(passageId)); OriginalText=Guard.Required(originalText,nameof(originalText)); RevisedText=Guard.Required(revisedText,nameof(revisedText)); ResolvedRevisionItemIds=Guard.Copy(resolvedRevisionItemIds,nameof(resolvedRevisionItemIds)); if(ResolvedRevisionItemIds.Count==0||ResolvedRevisionItemIds.Any(string.IsNullOrWhiteSpace)||ResolvedRevisionItemIds.Distinct(StringComparer.Ordinal).Count()!=ResolvedRevisionItemIds.Count)throw new ArgumentException("Resolved revision item IDs must be nonempty and unique.",nameof(resolvedRevisionItemIds)); }
    public string WorkItemId{get;} public string PassageId{get;} public string OriginalText{get;} public string RevisedText{get;} public IReadOnlyList<string> ResolvedRevisionItemIds{get;}
}

public sealed class DocumentaryNarrativeRevisionSubmission
{
    public DocumentaryNarrativeRevisionSubmission(string submissionId,string workPackageId,string revisionRequestId,string draftId,string draftVersion,DocumentaryNarrativeRevisionSubmissionMetadata metadata,IReadOnlyList<DocumentaryNarrativePassageRevisionSubmission> passageSubmissions)
    { SubmissionId=Guard.Required(submissionId,nameof(submissionId)); WorkPackageId=Guard.Required(workPackageId,nameof(workPackageId)); RevisionRequestId=Guard.Required(revisionRequestId,nameof(revisionRequestId)); DraftId=Guard.Required(draftId,nameof(draftId)); DraftVersion=Guard.Required(draftVersion,nameof(draftVersion)); Metadata=metadata??throw new ArgumentNullException(nameof(metadata)); PassageSubmissions=Guard.Copy(passageSubmissions,nameof(passageSubmissions)); if(PassageSubmissions.Select(x=>x.WorkItemId).Distinct(StringComparer.Ordinal).Count()!=PassageSubmissions.Count||PassageSubmissions.Select(x=>x.PassageId).Distinct(StringComparer.Ordinal).Count()!=PassageSubmissions.Count||PassageSubmissions.SelectMany(x=>x.ResolvedRevisionItemIds).Distinct(StringComparer.Ordinal).Count()!=ResolvedRevisionItemCount)throw new ArgumentException("Submission work, passage, and resolved item identities must be unique.",nameof(passageSubmissions)); }
    public string SubmissionId{get;} public string WorkPackageId{get;} public string RevisionRequestId{get;} public string DraftId{get;} public string DraftVersion{get;} public DocumentaryNarrativeRevisionSubmissionMetadata Metadata{get;} public IReadOnlyList<DocumentaryNarrativePassageRevisionSubmission> PassageSubmissions{get;} public int PassageSubmissionCount=>PassageSubmissions.Count; public int ResolvedRevisionItemCount=>PassageSubmissions.Sum(x=>x.ResolvedRevisionItemIds.Count);
}
